-- Production foundation only. No appointments, flats, policies, balances or payments seeded.
-- All financial mutations require audited server transactions/RPCs; no client write grants.
begin;
create table public.committee_appointments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),position text not null check(position in ('president','vice_president')),status text not null check(status in ('invited','accepted','active','revoked','resigned')),appointed_by uuid not null references auth.users(id),appointed_at timestamptz not null default now(),accepted_at timestamptz,starts date not null,ends date not null,check(ends>starts),check(status<>'active' or accepted_at is not null),unique(id,project_id));
create unique index one_project_position on public.committee_appointments(project_id,position) where status='active';
create unique index distinct_project_representatives on public.committee_appointments(project_id,user_id) where status='active';
create function private.project_member(uid uuid,pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m join public.flats f on f.id=m.flat_id where m.user_id=uid and f.project_id=pid and m.status='approved' and m.move_in<=now() and (m.move_out is null or m.move_out>now()));$$;
create function private.project_relationship(uid uuid,pid uuid) returns boolean language sql stable security definer set search_path='' as $$select private.project_member(uid,pid) or exists(select 1 from public.ownership o join public.flats f on f.id=o.flat_id where o.user_id=uid and f.project_id=pid);$$;
create function private.project_committee(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select private.project_relationship((select auth.uid()),pid) and exists(select 1 from public.committee_appointments a where a.project_id=pid and a.user_id=(select auth.uid()) and a.status='active' and a.starts<=(now() at time zone 'Asia/Kolkata')::date and a.ends>(now() at time zone 'Asia/Kolkata')::date);$$;
-- Platform/association staff roles intentionally absent from financial authorization.
create table public.project_settings(project_id uuid primary key references public.projects(id),enabled boolean not null default false,start_date date,policy jsonb not null default '{}',opening_cash bigint not null default 0,opening_reserve bigint not null default 0);
create unique index flat_project_scope on public.flats(id,project_id);
create table public.project_flat_liability(flat_id uuid primary key references public.flats(id),project_id uuid not null references public.projects(id),payer_id uuid not null references auth.users(id),area numeric,area_verified boolean not null default false,opening_due bigint not null default 0,exemption bigint not null default 0,unique(flat_id,project_id),foreign key(flat_id,project_id) references public.flats(id,project_id));
create table public.billing_periods(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),month date not null,state text not null check(state in ('draft','review','published','closed')),snapshot jsonb,unique(project_id,month),unique(id,project_id));
create table public.flat_invoices(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),period_id uuid not null,flat_id uuid not null,payer_id uuid not null references auth.users(id),due_date date not null,lines jsonb not null,amount bigint not null check(amount>=0),foreign key(period_id,project_id) references public.billing_periods(id,project_id),foreign key(flat_id,project_id) references public.project_flat_liability(flat_id,project_id),unique(period_id,flat_id),unique(id,project_id));
create table public.invoice_adjustments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),invoice_id uuid not null,amount bigint not null,reason text not null,effective_month date not null,actor uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(invoice_id,project_id) references public.flat_invoices(id,project_id));
create table public.project_attachments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),owner_id uuid not null references auth.users(id),name text not null,mime text not null,object_key text unique not null,visibility text not null check(visibility in ('private','redacted')),scan_state text not null default 'quarantined' check(scan_state in ('quarantined','clean','rejected')),unique(id,project_id));
create table public.payment_submissions(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),invoice_id uuid not null,amount bigint not null check(amount>0),reference text not null,attachment_id uuid,status text not null default 'submitted' check(status in ('submitted','verified','rejected')),request_key text not null,created_at timestamptz not null default now(),foreign key(invoice_id,project_id) references public.flat_invoices(id,project_id),foreign key(attachment_id,project_id) references public.project_attachments(id,project_id),unique(user_id,request_key),unique(project_id,reference),unique(id,project_id));
create table public.project_receipts(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),submission_id uuid not null unique,amount bigint not null check(amount>0),allocated bigint not null check(allocated>=0 and allocated<=amount),received_on date not null,verified_by uuid not null references auth.users(id),check(verified_by<>user_id),foreign key(submission_id,project_id) references public.payment_submissions(id,project_id));
create table public.credit_allocations(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),invoice_id uuid not null,amount bigint not null check(amount>0),created_at timestamptz not null default now(),foreign key(invoice_id,project_id) references public.flat_invoices(id,project_id));
create table public.project_expense_bills(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),category text not null,description text not null,period date not null,vendor text not null,bill_date date not null,bill_number text not null,amount bigint not null,due_date date not null,status text not null check(status in ('pending','approved')),created_by uuid not null references auth.users(id),reviewed_by uuid references auth.users(id),attachment_id uuid,redacted_attachment_id uuid,details jsonb not null default '{}',service_request_id uuid unique references public.service_requests(id),created_at timestamptz not null default now(),foreign key(attachment_id,project_id) references public.project_attachments(id,project_id),foreign key(redacted_attachment_id,project_id) references public.project_attachments(id,project_id),unique(project_id,vendor,bill_number),unique(id,project_id));
create table public.project_expense_payments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),bill_id uuid not null,amount bigint not null check(amount>0),paid_on date not null,method text not null,reference text not null,actor uuid not null references auth.users(id),request_key text not null,foreign key(bill_id,project_id) references public.project_expense_bills(id,project_id),unique(project_id,request_key));
create table public.project_cash(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),fund text not null check(fund in ('general','reserve')),amount bigint not null,paid_on date not null,source text unique not null,description text not null);
create table public.project_questions(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),category text not null,subject text not null,body text not null,visibility text not null default 'private' check(visibility in ('private','project')),status text not null default 'open',assigned_to uuid references auth.users(id),attachment_id uuid,faq_consent boolean not null default false,created_at timestamptz not null default now(),foreign key(attachment_id,project_id) references public.project_attachments(id,project_id),unique(id,project_id));
create table public.project_replies(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),question_id uuid not null,user_id uuid not null references auth.users(id),body text not null,created_at timestamptz not null default now(),foreign key(question_id,project_id) references public.project_questions(id,project_id));
create table public.project_operations(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),kind text not null,title text not null,payload jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,project_id));
create table public.project_votes(project_id uuid not null references public.projects(id),operation_id uuid not null,user_id uuid not null references auth.users(id),choice text not null,primary key(operation_id,user_id),foreign key(operation_id,project_id) references public.project_operations(id,project_id));
create table public.project_history(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),actor uuid not null references auth.users(id),kind text not null,target uuid not null,details text not null,created_at timestamptz not null default now());
-- Only redacted projections may be published to the entire project. Never copy payer ledgers or bank details.
create table public.project_published_accounts(project_id uuid not null references public.projects(id),month date not null,summary jsonb not null,published_at timestamptz not null default now(),primary key(project_id,month));
create table public.project_published_bills(id uuid primary key,project_id uuid not null references public.projects(id),category text not null,description text not null,period date not null,amount bigint not null,paid bigint not null,redacted_attachment_id uuid,foreign key(redacted_attachment_id,project_id) references public.project_attachments(id,project_id));
create table public.exchange_listings(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),user_id uuid not null references auth.users(id),title text not null check(length(title) between 1 and 100),description text not null check(length(description) between 1 and 2500),category text not null,condition text not null,type text not null check(type in ('sale','free','wanted','exchange')),price bigint not null check(price>=0),audience text not null default 'project' check(audience in ('project','network')),status text not null default 'draft' check(status in ('draft','active','reserved','sold','withdrawn','expired')),photo_keys jsonb not null default '[]',exchange_preference text not null default '',created_at timestamptz not null default now(),expires timestamptz not null,request_key text not null,unique(user_id,request_key));
create table public.exchange_saves(user_id uuid not null references auth.users(id),listing_id uuid not null references public.exchange_listings(id),primary key(user_id,listing_id));
create table public.exchange_conversations(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.exchange_listings(id),buyer_id uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(listing_id,buyer_id));
create table public.exchange_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.exchange_conversations(id),user_id uuid not null references auth.users(id),body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now(),request_key text not null,unique(user_id,request_key));
create table private.exchange_reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),kind text not null,target_id uuid not null,reason text not null,status text not null default 'open',created_at timestamptz not null default now());
create function private.exchange_visible(lid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exchange_listings l where l.id=lid and private.active_resident((select auth.uid())) and private.project_member(l.user_id,l.project_id) and not private.are_blocked((select auth.uid()),l.user_id) and (l.user_id=(select auth.uid()) or (l.status not in ('draft','withdrawn') and (l.audience='network' or private.project_member((select auth.uid()),l.project_id)))));$$;
create function private.exchange_participant(cid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.exchange_conversations c join public.exchange_listings l on l.id=c.listing_id where c.id=cid and (c.buyer_id=(select auth.uid()) or l.user_id=(select auth.uid())) and private.exchange_visible(l.id) and private.active_resident(c.buyer_id) and not private.are_blocked(c.buyer_id,l.user_id));$$;
create function private.project_question_visible(qid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.project_questions q where q.id=qid and private.project_relationship((select auth.uid()),q.project_id) and (q.user_id=(select auth.uid()) or q.visibility='project' or private.project_committee(q.project_id)));$$;
do $$declare t text;begin foreach t in array array['committee_appointments','project_settings','project_flat_liability','billing_periods','flat_invoices','invoice_adjustments','project_attachments','payment_submissions','project_receipts','credit_allocations','project_expense_bills','project_expense_payments','project_cash','project_questions','project_replies','project_operations','project_votes','project_history','project_published_accounts','project_published_bills','exchange_listings','exchange_saves','exchange_conversations','exchange_messages'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
create policy committee_directory on public.committee_appointments for select to authenticated using(user_id=(select auth.uid()) or private.project_relationship((select auth.uid()),project_id) or private.staff_role(array['platform']));
create function private.published_invoice(iid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.flat_invoices i join public.billing_periods p on p.id=i.period_id and p.project_id=i.project_id where i.id=iid and p.state in ('published','closed'));$$;
revoke all on function private.published_invoice(uuid) from public,anon;
grant execute on function private.published_invoice(uuid) to authenticated;
-- Raw settings contain opening financial records; authorized server supplies redacted policy to residents.
create policy committee_settings on public.project_settings for select to authenticated using(private.project_committee(project_id));
create policy committee_liability on public.project_flat_liability for select to authenticated using(private.project_committee(project_id));
create policy project_periods on public.billing_periods for select to authenticated using(private.project_committee(project_id)); -- snapshots raw: published projections are separate
create policy own_project_invoice on public.flat_invoices for select to authenticated using(private.project_committee(project_id) or (payer_id=(select auth.uid()) and private.project_relationship((select auth.uid()),project_id) and private.published_invoice(id)));
create policy own_invoice_adjustments on public.invoice_adjustments for select to authenticated using(private.project_committee(project_id) or exists(select 1 from public.flat_invoices i where i.id=invoice_id and i.payer_id=(select auth.uid())));
create function private.bill_attachment(aid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.project_expense_bills b where b.attachment_id=aid or b.redacted_attachment_id=aid);$$;
revoke all on function private.bill_attachment(uuid) from public,anon;
grant execute on function private.bill_attachment(uuid) to authenticated;
create policy private_project_attachments on public.project_attachments for select to authenticated using(private.project_relationship((select auth.uid()),project_id) and ((owner_id=(select auth.uid()) and not private.bill_attachment(id)) or private.project_committee(project_id) or (visibility='redacted' and scan_state='clean' and exists(select 1 from public.project_published_bills b where b.redacted_attachment_id=project_attachments.id and b.project_id=project_attachments.project_id))));
create policy own_payment_submissions on public.payment_submissions for select to authenticated using(private.project_relationship((select auth.uid()),project_id) and (user_id=(select auth.uid()) or private.project_committee(project_id)));
create policy own_project_receipts on public.project_receipts for select to authenticated using(private.project_relationship((select auth.uid()),project_id) and (user_id=(select auth.uid()) or private.project_committee(project_id)));
create policy own_credits on public.credit_allocations for select to authenticated using(private.project_relationship((select auth.uid()),project_id) and (user_id=(select auth.uid()) or private.project_committee(project_id)));
do $$declare t text;begin foreach t in array array['project_expense_bills','project_expense_payments','project_cash','project_history'] loop execute format('create policy committee_only on public.%I for select to authenticated using(private.project_committee(project_id))',t);end loop;end$$;
create policy visible_questions on public.project_questions for select to authenticated using(private.project_question_visible(id));
create policy visible_replies on public.project_replies for select to authenticated using(private.project_question_visible(question_id));
create policy community_operations on public.project_operations for select to authenticated using(private.project_committee(project_id) or (private.project_relationship((select auth.uid()),project_id) and kind in ('notice','meeting','asset','faq','poll')));
create policy own_opinion_vote on public.project_votes for select to authenticated using(private.project_relationship((select auth.uid()),project_id) and (user_id=(select auth.uid()) or private.project_committee(project_id)));
create policy published_accounts on public.project_published_accounts for select to authenticated using(private.project_relationship((select auth.uid()),project_id));
create policy published_bills on public.project_published_bills for select to authenticated using(private.project_relationship((select auth.uid()),project_id));
create policy resident_exchange on public.exchange_listings for select to authenticated using(private.exchange_visible(id));
create policy own_saved_items on public.exchange_saves for select to authenticated using(user_id=(select auth.uid()) and private.exchange_visible(listing_id));
create policy listing_participants on public.exchange_conversations for select to authenticated using(private.exchange_participant(id));
create policy listing_messages on public.exchange_messages for select to authenticated using(private.exchange_participant(conversation_id));
alter table private.exchange_reports enable row level security;
revoke all on private.exchange_reports from anon,authenticated;
revoke all on function private.project_member(uuid,uuid),private.project_relationship(uuid,uuid),private.project_committee(uuid),private.exchange_visible(uuid),private.exchange_participant(uuid),private.project_question_visible(uuid) from public,anon;
grant execute on function private.project_member(uuid,uuid),private.project_relationship(uuid,uuid),private.project_committee(uuid),private.exchange_visible(uuid),private.exchange_participant(uuid),private.project_question_visible(uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-bills','project-bills',false,2000000,array['application/pdf','image/jpeg','image/png']),('resident-exchange','resident-exchange',false,400000,array['image/jpeg','image/png']) on conflict(id) do nothing;
-- No direct storage policies. Signed operations must check project/participant scope and scan_state.
-- Numeric register conversion is deliberately NOT inferred from totals: authorized import + collision report required.
commit;
